CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships(tenant TEXT NOT NULL, owner TEXT NOT NULL, project TEXT NOT NULL, PRIMARY KEY(tenant,owner,project));
CREATE TABLE import_batches(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('preview','applied','rolled_back')), file TEXT NOT NULL, report TEXT NOT NULL CHECK(json_valid(report)), reviewer TEXT, approved_at TEXT, UNIQUE(tenant,hash));
CREATE TABLE materials(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, external_key TEXT NOT NULL, description TEXT NOT NULL, product_uom TEXT NOT NULL CHECK(product_uom IN ('EA','FT','STICK','BOX','ROLL','PAIR')), details TEXT NOT NULL CHECK(json_valid(details)), dataset_kind TEXT NOT NULL CHECK(dataset_kind IN ('fixture','reviewed')), batch_id TEXT NOT NULL REFERENCES import_batches(id), active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant,external_key));
CREATE TABLE aliases(material_id TEXT NOT NULL REFERENCES materials(id), normalized TEXT NOT NULL, requested_uom TEXT NOT NULL, PRIMARY KEY(material_id,normalized));
CREATE INDEX alias_search ON aliases(normalized);
CREATE INDEX material_tenant ON materials(tenant,active);
CREATE TABLE drafts(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, owner TEXT NOT NULL, project TEXT NOT NULL, delivery_date TEXT NOT NULL, version INTEGER NOT NULL, updated_at TEXT NOT NULL, UNIQUE(tenant,owner,project));
CREATE TABLE draft_lines(id TEXT NOT NULL, draft_id TEXT NOT NULL REFERENCES drafts(id) ON DELETE CASCADE, position INTEGER NOT NULL, material_id TEXT REFERENCES materials(id), quantity TEXT NOT NULL, requested_uom TEXT NOT NULL, description TEXT NOT NULL, raw_input TEXT NOT NULL CHECK(json_valid(raw_input)), candidate TEXT CHECK(candidate IS NULL OR json_valid(candidate)), source TEXT NOT NULL CHECK(source IN ('verified','verified_fixture','ai_fixture','user_description')), delivery_mode TEXT NOT NULL CHECK(delivery_mode IN ('inherit','override')), override_date TEXT, PRIMARY KEY(draft_id,id), CHECK((delivery_mode='inherit' AND override_date IS NULL) OR (delivery_mode='override' AND override_date IS NOT NULL)));
CREATE TABLE audit_events(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE image_associations(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES materials(id), content_hash TEXT NOT NULL, source_url TEXT NOT NULL, rights_basis TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')), reviewer TEXT, reviewed_at TEXT, UNIQUE(tenant,material_id,content_hash));
